"""Record independent human/model visual decisions after vision_analyze inspection.
Does not infer approval from manifest GO fields. Run icons-audit.py first.
"""
from pathlib import Path
import json, hashlib
from collections import Counter
OUT=Path(__file__).parent
technical=json.loads((OUT/'icons-technical.json').read_text())
notes=[
 ('Dome and tower give a strong city/architecture silhouette; red dome survives 32px. Fine roof detail merges but does not undermine category.', 'City architecture at all tested sizes; not an identifier for every city in its worksheet group.'),
 ('Colosseum mass and stacked arches remain recognizable; arches soften at 32px without export-specific damage.', 'City/monument category; 48px or larger preferred for the arches.'),
 ('Vertical tower cluster reads as town at 48-96px. At 32px dense foliage competes with the small towers; visually distinct from the dome/arena but not a unique city-group identifier.', 'Town category with label; prefer 64-96px for tower detail.'),
 ('Cliffside buildings and blue bay read as coastal settlement at 48-96px. At 32px buildings collapse into warm texture, so exact city-group meaning depends on the live label.', 'Coastal town/category cue, not a map or item-specific city representation; prefer 64-96px.'),
 ('Green rocky promontory and turquoise coves read as coast, not unambiguously as an island. Even 96px does not establish an enclosed island outline. Acceptable supporting Eilanden illustration only with a live label; must not teach island geometry.', 'Labelled Eilanden decoration only; 48-96px preferred. Not a standalone island-recognition test.'),
 ('Pale jagged mountain skyline is clear from 32px. Foreground meadow softens at small sizes; mountain category remains intact.', 'Mountain category at all tested sizes, not geographic extent evidence.'),
 ('Cone and eruption plume distinguish volcano from the non-erupting mountain illustration at 48-96px; at 32px plume is small but silhouette remains useful.', 'Volcano category at all tested sizes with label; 48px or larger preferred.'),
 ('Rolling fields, cypresses and winding road convey countryside/region, not a bounded administrative region. At 32px field texture dominates; no claim that scenery alone names Streken.', 'Labelled landscape/regions cue; 48-96px preferred, 64-96px to appreciate fields.'),
 ('Italian tricolor border stone and direction boards support border/countries meaning at 48-96px. At 32px this can read as mountain scenery with a post. Baked words are too small to read at all four UI sizes. Native crop shows correct Dutch Frankrijk, Zwitserland, Oostenrijk; decorative directions are not geography.', 'Labelled Landen cue only, preferably 64-96px; never rely on sign words or arrow orientation as learning content.'),
 ('Blue open water and wave band read as sea from 32px. Native left edge is tangent/clipped: master has 69 left-edge nonzero pixels, maximum alpha 185; export left edge has 57 nonzero pixels, maximum 226, plus 40 top-edge alpha-3 pixels. Native strip and all small-size boards show no conspicuous flat cut or stray matte. Nonblocking within tested 32-96px use; do not certify pristine native/master edge.', 'Sea category at all tested sizes with label. Existing edge contact accepted only for reviewed small-size use; inspect again for larger display or master remediation.'),
 ('Blue river corridor and multi-arch bridge remain recognizable at 48-96px; at 32px the bridge/vegetation compresses, but watercourse is still useful beside a label.', 'River category with live label; 48-96px preferred, not a specific river map.')
]
assert len(notes)==len(technical['icons'])==11
result={'revision':technical['revision'],'manifest_sha256':technical['manifest_sha256'], 'audit_type':'Independent bounded visual QA, not export approval ledger or implementation approval', 'verdict_definition':'PASS means existing art is acceptable for the constrained labelled UI uses below; not standalone semantic identification, source restoration, geography certification or native-size master approval.', 'inspection':{'tool':'vision_analyze','boards':['icons-sizes-warm.png','icons-sizes-dark.png','icons-sizes-checker.png','icons-overview-01-06.png','icons-overview-07-11.png','icons-native-details.png'], 'coverage':'All 11 masters and all 11 exports at 32/48/64/96 on each background. Full boards initially downscaled by tool; all size boards subsequently re-inspected as upper/lower crops at native display resolution. Larger paired 256px views and native sea-edge/country-sign details also inspected.', 'sample_count':11*2*4*3,'backgrounds':{'warm':'#f5ead6','dark':'#17252b','checker':['#eeeeee','#b9b9b9']},'resampler':'Pillow LANCZOS; PNG downsized directly from 1254, export downsized from existing 512 WebP; not browser/device screenshots.'}, 'common_findings':['No visible export-specific silhouette/color shift, objectionable compression block, opaque rectangular matte or unintended broad alpha halo in the reviewed renders. Cream circular rim is present in masters and is intentional artwork, not a newly introduced export halo.', 'All 22 actual asset hashes match the manifest; masters are 1254x1254 RGBA PNG, exports 512x512 RGBA WebP. No embedded ICC profiles; do not claim independently verified sRGB conversion.', 'Exports 05/06/08/09/11 have outer-edge alpha at most 4 from resampling; not visibly objectionable. Sea 10 has genuine native left-edge contact, separately documented.', 'All icons require adjacent readable live UI labels. Do not bake labels into the images or depend on small country-sign text. Icons are supporting chapter artwork, not exact category/item maps.'], 'limitations':['Upstream pre-cleanup original source files are not provided by the supplied manifest paths; source_sha256 is retained as an unverified upstream claim separately from verified PNG master hash.', 'This audit does not check UI integration, accessible text implementation, device/browser resampling, color-managed display equivalence or legal provenance. Parent owns full ledger, export approval and status metadata.'], 'icons':[]}
for r,(reason,usage) in zip(technical['icons'],notes):
    ok=all(f['technical_pass'] for f in r['files'].values())
    result['icons'].append({'id':r['id'],'title':r['title'],'verdict':'PASS' if ok else 'BLOCKED','reasons':[reason,'Independent comparison of master/export across warm, dark and checker found no additional small-size defect requiring regeneration.'], 'source_path':r['files']['master']['path'],'source_sha256':r['files']['master']['sha256'],'export_path':r['files']['export']['path'],'export_sha256':r['files']['export']['sha256'],'upstream_source_sha256_unverified':r['upstream_source_sha256_manifest_only'],'technical':r['files'], 'approved_size_usage':{'css_px':[32,48,64,96], '32px':'Supporting/decorative thumbnail with adjacent live category/chapter label only; not a standalone identifier. Dense scenes lose fine detail.', '48_64_96px':usage,'live_ui_label_required':True,'baked_words_required_to_read':False,'backgrounds':['warm','dark','checker'],'larger_than_96px':'Not approved by this bounded small-size QA.'}, 'production_source_recommendation':{'recommended':ok,'path':r['files']['export']['path'],'sha256':r['files']['export']['sha256'],'condition':'Use existing verified 512 WebP as source only for reviewed labelled 32/48/64/96 CSS-px usage; parent retains integration/export approval.'}})
result['totals']=dict(Counter(r['verdict'] for r in result['icons']))
result['evidence_sha256']={name:hashlib.sha256((OUT/name).read_bytes()).hexdigest() for name in result['inspection']['boards']}
(OUT/'icons-verdicts.json').write_text(json.dumps(result,indent=2,ensure_ascii=False)+'\n')
print(json.dumps({'count':len(result['icons']),'totals':result['totals'],'sample_count':result['inspection']['sample_count'],'all_source_hashes_present':all(len(r['source_sha256'])==64 and len(r['export_sha256'])==64 for r in result['icons'])}))
